css:
table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 10px;
}

table.table-none {
    margin-bottom: 0;
}

th,
td {
    border: 1px solid #808080;
    padding: 8px;
    text-align: left;
}

.none-border-td,
.none-border {
    border: none;
}

.none-border th,
.none-border td {
    border: none;
}

.body-part {
    border: 1px solid #808080;
    padding: 10px;
}

body:last-child .print-format .none-border td img {
    width: auto !important;
}

.align-left {
    text-align: left;
}

.align-center {
    text-align: center;
}

.align-right {
    text-align: right;
}

.none-border .vertical-middle {
    vertical-align: middle !important;
}

h3 {
    border: solid 1px #ccc;
}

p {
    font-size: 18px;
}

.print-format td span div p {
    font-size: 9pt;
}

.none-border tbody td {
    width: auto;
}

tbody td {
    width: 100px;
}
body .print-format td{
    padding: 4px !important;
}
